package com.governai.decision;import java.time.OffsetDateTime;import java.util.UUID;public record ApprovalResponse(UUID id,UUID decisionRequestId,UUID reviewerId,ApprovalAction action,String originalRecommendation,String finalDecision,String reviewerComment,OffsetDateTime reviewedAt){static ApprovalResponse from(Approval a){return new ApprovalResponse(a.getId(),a.getDecisionRequestId(),a.getReviewerId(),a.getAction(),a.getOriginalRecommendation(),a.getFinalDecision(),a.getReviewerComment(),a.getReviewedAt());}}
